const MAJ = ["The Fool","The Magician","The High Priestess","The Empress","The Emperor","The Hierophant","The Lovers","The Chariot","Strength","The Hermit","Wheel of Fortune","Justice","The Hanged Man","Death","Temperance","The Devil","The Tower","The Star","The Moon","The Sun","Judgement","The World"];
const NUMS = ["Ace","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Page","Knight","Queen","King"];
const SUITS: Record<string, [string, string]> = { Wands: ["fire", "passion, drive and creative energy"], Cups: ["water", "emotions, love and relationships"], Swords: ["air", "thought, truth and conflict"], Pentacles: ["earth", "money, work and the body"] };
const NM: Record<string, [string, string]> = { Ace: ["a fresh start and raw potential", "a missed chance, delay or false start"], Two: ["balance, choice and partnership", "indecision, imbalance or a stalled choice"], Three: ["growth, teamwork and first results", "poor teamwork, delays or scattered effort"], Four: ["stability, rest and structure", "stagnation, restlessness or resisting change"], Five: ["conflict, loss or a test", "recovery after conflict, or avoiding the problem"], Six: ["harmony, help and moving on", "unfinished business or help with strings attached"], Seven: ["assessment, patience and a challenge", "giving up too soon, or avoiding the real work"], Eight: ["movement, skill and focus", "blocks, scattered energy or feeling stuck"], Nine: ["near completion and resilience", "exhaustion, anxiety or going it alone too long"], Ten: ["completion, a full cycle and its weight", "burnout, an ending dragged out or release of a burden"], Page: ["curiosity, news and a willing beginner", "immaturity, mixed messages or fear of trying"], Knight: ["action, pursuit and momentum", "recklessness, burnout or stalled drive"], Queen: ["maturity, care and inner mastery", "insecurity, smothering or neglecting your own needs"], King: ["authority, control and outer mastery", "control issues, misuse of power or rigidity"] };
const EXTRA: Record<string, string[]> = { temperance: ["temperance", "temperance tarot card"], "the-world": ["the world"], "the-hierophant": ["hierophant"], "the-tower": ["tower"], "the-moon": ["the moon tarot", "the moon tarot card meaning"], "the-lovers": ["the lovers", "the lovers tarot", "the lovers tarot card"], "wheel-of-fortune": ["wheel of fortune"], "knight-of-cups": ["knight of cups"] };
const slugify = (n: string) => n.toLowerCase().replace(/[^a-z]+/g, "-").replace(/^-|-$/g, "");
export const CARD_PAGES: SeoPageDef[] = [
  ...MAJ.map((name) => ({ name, arcana: "Major Arcana", img: "/tarot/" + name.toLowerCase().replace(/[^a-z]+/g, "_").replace(/^_|_$/g, "") + ".jpg" })),
  ...Object.keys(SUITS).flatMap((suit) => NUMS.map((num) => ({ name: num + " of " + suit, arcana: "Minor Arcana", img: "/tarot/" + (num + " of " + suit).toLowerCase().replace(/ /g, "_") + ".jpg", suit, num, el: SUITS[suit][0], dom: SUITS[suit][1], up: NM[num][0], rev: NM[num][1] }))),
].map((c) => {
  const slug = slugify(c.name);
  const lc = c.name.toLowerCase();
  const kws = Array.from(new Set([lc, lc + " tarot", lc + " tarot card meaning", ...(EXTRA[slug] || []), ...(RESEARCH_KEYWORDS["/tarot-card-meanings/" + slug] || [])]));
  return { path: "/tarot-card-meanings/" + slug, kind: "card", kw: kws[2], kws, title: (c.name.length < 10 ? c.name + " Tarot Card Meaning Guide" : c.name + " Tarot Card Meaning") + " | The Psychic Studio", h1: c.name + " Tarot Card Meaning", meta: c.name + " tarot card meaning: upright and reversed, love, career and advice. A clear guide to " + (c.name.startsWith("The ") ? c.name : "the " + c.name) + " in a reading.", intro: c.name + " tarot card meaning brings together upright and reversed interpretations. Read the card in the context of your question, its position in a spread and the cards around it.", links: ["/tarot-card-meanings", "/free-tarot", "/shop", "/faq"], card: { ...c, slug } } as SeoPageDef;
});
export const ALL_SEO_PAGES: SeoPageDef[] = [...SEO_PAGES, ...CARD_PAGES];
